  <script>
    const categories = ["All", "Home", "Wear", "Tech", "Beauty"];
    const products = [
      { name: "Lumen Table Lamp", category: "Home", price: "$84", rating: "4.9", text: "Soft ambient light with brushed metal detailing.", badge: "Best seller", emoji: "◐", gradient: "linear-gradient(135deg, #6d28d9, #22d3ee)" },
      { name: "Aero Knit Jacket", category: "Wear", price: "$128", rating: "4.8", text: "Lightweight layering with a sculpted fit.", badge: "New", emoji: "✦", gradient: "linear-gradient(135deg, #f97316, #ec4899)" },
      { name: "Pulse Speaker", category: "Tech", price: "$96", rating: "4.7", text: "Room-filling audio in a compact matte finish.", badge: "Deal", emoji: "◉", gradient: "linear-gradient(135deg, #14b8a6, #7c3aed)" },
      { name: "Velvet Skin Serum", category: "Beauty", price: "$42", rating: "5.0", text: "A smoothing nightly formula with ceramide support.", badge: "Top rated", emoji: "✿", gradient: "linear-gradient(135deg, #db2777, #7c5cff)" },
      { name: "Orbit Side Bag", category: "Wear", price: "$74", rating: "4.8", text: "Structured silhouette with adjustable carry options.", badge: "Limited", emoji: "◆", gradient: "linear-gradient(135deg, #0ea5e9, #f59e0b)" },
      { name: "Cinder Throw", category: "Home", price: "$58", rating: "4.9", text: "Weighty texture and a deep charcoal weave.", badge: "Editor pick", emoji: "☾", gradient: "linear-gradient(135deg, #334155, #7c5cff)" },
      { name: "Halo Watch", category: "Tech", price: "$179", rating: "4.6", text: "Minimal smartwatch with vibrant always-on display.", badge: "Trending", emoji: "◎", gradient: "linear-gradient(135deg, #111827, #38bdf8)" },
      { name: "Glow Brush Set", category: "Beauty", price: "$36", rating: "4.9", text: "Five pro-grade tools with a soft-touch finish.", badge: "Value", emoji: "❖", gradient: "linear-gradient(135deg, #f59e0b, #ec4899)" }
    ];

    const tabs = document.querySelector(".tabs");
    const grid = document.getElementById("product-grid");
    const dealEndsAt = new Date(Date.now() + 1000 * 60 * 60 * 7 + 1000 * 60 * 38 + 1000 * 42);
    const activeCategory = { value: "All" };

    function renderTabs() {
      tabs.innerHTML = categories.map((category) => `
        <button class="tab ${category === activeCategory.value ? "active" : ""}" data-category="${category}" role="tab" aria-selected="${category === activeCategory.value}">
          ${category}
        </button>
      `).join("");
    }

    function renderProducts() {
      const selected = activeCategory.value;
      const visible = products.filter((product) => selected === "All" || product.category === selected);

      grid.innerHTML = visible.map((product) => `
        <article class="product">
          <div class="product-media">
            <span class="product-badge">${product.badge}</span>
            <div class="product-art" style="--product-gradient:${product.gradient}">
              <span>${product.emoji}</span>
            </div>
          </div>
          <div class="product-body">
            <div class="product-meta">
              <span>${product.category}</span>
              <span class="rating">★ ${product.rating}</span>
            </div>
            <h3>${product.name}</h3>
            <p>${product.text}</p>
            <div class="product-meta">
              <span class="price">${product.price}</span>
              <span>Free shipping</span>
            </div>
            <div class="product-actions">
              <a class="btn primary" href="#top">Add to cart</a>
              <a class="btn" href="#editorial">Details</a>
            </div>
          </div>
        </article>
      `).join("");
    }

    tabs.addEventListener("click", (event) => {
      const button = event.target.closest("[data-category]");
      if (!button) return;
      activeCategory.value = button.dataset.category;
      renderTabs();
      renderProducts();
    });

    function tickDealTimer() {
      const diff = Math.max(0, dealEndsAt - new Date());
      const totalSeconds = Math.floor(diff / 1000);
      const hours = String(Math.floor(totalSeconds / 3600)).padStart(2, "0");
      const minutes = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0");
      const seconds = String(totalSeconds % 60).padStart(2, "0");

      document.getElementById("hours").textContent = hours;
      document.getElementById("minutes").textContent = minutes;
      document.getElementById("seconds").textContent = seconds;
    }

    renderTabs();
    renderProducts();
    tickDealTimer();
    setInterval(tickDealTimer, 1000);
  </script>
