     function renderTabs() {
       tabs.innerHTML = categories.map((category) => `
         <button class="tab ${category === activeCategory.value ? "active" : ""}" data-category="${category}" role="tab" aria-selected="${category === activeCategory.value}">
           ${category}
         </button>
       `).join("");
